WiFiStatus wifi_station_connect(void) {
    if (strlen(s_ssid) == 0) {
        if (!loadCredentials()) {
            notifyStatusChange(WIFI_STATUS_NO_CREDENTIALS);
            return WIFI_STATUS_NO_CREDENTIALS;
        }
    }
    
    ESP_LOGI(TAG, "Connecting to: %s", s_ssid);
    notifyStatusChange(WIFI_STATUS_CONNECTING);
    
    // Configure WiFi
    wifi_config_t wifi_config = {};
    strncpy((char*)wifi_config.sta.ssid, s_ssid, sizeof(wifi_config.sta.ssid));
    strncpy((char*)wifi_config.sta.password, s_password, sizeof(wifi_config.sta.password));
    wifi_config.sta.threshold.authmode = strlen(s_password) > 0 ? WIFI_AUTH_WPA2_PSK : WIFI_AUTH_OPEN;
    
    esp_wifi_set_mode(WIFI_MODE_STA);
    esp_wifi_set_config(WIFI_IF_STA, &wifi_config);
    esp_wifi_start();
    
    s_last_connect_attempt = get_millis();
    
    // Wait for connection
    if (s_wifi_event_group) {
        EventBits_t bits = xEventGroupWaitBits(s_wifi_event_group,
            WIFI_CONNECTED_BIT | WIFI_FAIL_BIT,
            pdTRUE, pdFALSE,
            pdMS_TO_TICKS(WIFI_CONNECT_TIMEOUT_MS));
        
        if (bits & WIFI_CONNECTED_BIT) {
            ESP_LOGI(TAG, "Connected!");
            return WIFI_STATUS_CONNECTED;
        } else if (bits & WIFI_FAIL_BIT) {
            s_retry_count++;
            if (s_retry_count >= WIFI_MAX_RETRIES) {
                ESP_LOGE(TAG, "Max retries reached");
                notifyStatusChange(WIFI_STATUS_FAILED);
                return WIFI_STATUS_FAILED;
            }
            notifyStatusChange(WIFI_STATUS_DISCONNECTED);
            return WIFI_STATUS_DISCONNECTED;
        }
    }
    
    ESP_LOGW(TAG, "Connection timeout");
    s_retry_count++;
    return WIFI_STATUS_DISCONNECTED;
}

